import 'package:flutter/material.dart'; import '../models/poll.dart'; import '../services/poll_service.dart'; import '../widgets/page_frame.dart'; import 'participant_dashboard_screen.dart'; import 'results_screen.dart';
class PollVotingScreen extends StatefulWidget { const PollVotingScreen({super.key, required this.service, required this.poll}); final PollService service; final Poll poll; @override State<PollVotingScreen> createState() => _PollVotingState(); }
class _PollVotingState extends State<PollVotingScreen> { String? selected, error; void submit() async { if (selected == null) { setState(() => error = 'Select one candidate first.'); return; } final ok = await showDialog<bool>(context: context, builder: (_) => AlertDialog(title: const Text('Confirm vote'), content: const Text('Submit your vote? You cannot change it later.'), actions: [TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Submit'))])); if (ok == true) { final issue = await widget.service.submitVote(widget.poll, selected!); if (!mounted) return; if (issue != null) { setState(() => error = issue); } else { Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => ParticipantDashboardScreen(service: widget.service, poll: widget.poll))); } } }
 @override Widget build(BuildContext context) { widget.service.refresh(widget.poll); final closed = widget.poll.isClosed; return PageFrame(title: 'Vote', onBack: () => Navigator.pop(context), child: ListView(padding: const EdgeInsets.all(24), children: [Text(widget.poll.title, style: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold)), Text(widget.poll.description), const SizedBox(height: 20), if (error != null) Padding(padding: const EdgeInsets.only(bottom: 12), child: Text(error!, style: TextStyle(color: error!.contains('successfully') ? Colors.green : const Color(0xff3857d6), fontWeight: FontWeight.w600))), if (closed) const Card(child: Padding(padding: EdgeInsets.all(16), child: Text('Voting is closed for this poll.'))), for (final candidate in widget.poll.candidates) Card(child: RadioListTile<String>(value: candidate.id, groupValue: selected, onChanged: closed || widget.poll.voters.contains(widget.service.participantId) ? null : (v) => setState(() => selected = v), title: Text(candidate.name))), const SizedBox(height: 16), FilledButton(onPressed: closed ? null : submit, child: const Text('Submit Vote')), if (widget.poll.status == PollStatus.published) TextButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ResultsScreen(poll: widget.poll))), child: const Text('See Results'))])); }
}
